柯里化

是把接收多个参数的函数变成一个单一参数（最初函数的第一个参数）的函数，并且返回接收余下的参数而且返回结果的新函数的技术（累积函数的参数，最后延迟执行）

好处：

参数复用

// 普通函数
function check(reg, txt) {
    return reg.test(txt)
}
check(/\d+/g, 'test')     // false
check(/[a-z]+/g, 'test')  // true

// 复用第一个参数（正则规则），校验字符串
function curryCheck(reg) {
    return function(txt) {
        return reg.test(txt)
    }
}
const hasNumber = curryCheck(/\d+/g)
const hasLetter = curryCheck(/[a-z]+/g)
hasNumber('test')      // false
hasLetter('test')      // true


提前返回（提前确认）

// 浏览器监听事件
var on = function(element, type, fn) {
    if(window.addEventListener) {
        if(element && type && fn) {
            element.addEventListener(type, () => {
                fn.apply(element, arguments)
            })
        }
    }else {
        if(element && type && fn) {
            element.attachEvent('on' + type, () => {
                fn.apply(element, arguments)
            })
        }
    }
}

// 改装后（自执行后返回一个函数，提前确定了会走哪一个分支）
var on = (function() {
    if(window.addEventListener) {
        return function(element, type, fn) {
            if(element && type && fn) {
                element.addEventListener(type, () => {
                    fn.apply(element, arguments)
                })
            }
        }
    }else {
        return function(element, type, fn) {
            if(element && type && fn) {
                element.attachEvent('on' + type, () => {
                    fn.apply(element, arguments)
                })
            }
        }
    }
})()


