    }
}

new Foo() instanceof Foo     // false

// 说明：新生成的对象不在原构造函数的原型链上


对某个属性设置，getter 和 setter 存值函数和取值函数，拦截该属性的存取行为

class Point {
    constructor() {}

    get prop() {
        return 'getter'
    }
    set prop(value) {
        console.log('setter: ' + value)
    }
}

let point = new Point()

point.prop = 123      // setter: 123

point.prop            // "getter"


